use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{channel, Sender};

// Link the static library generated by Swift
#[link(name = "McWalkCore", kind = "static")]
extern "C" {
    fn mcwalk_enumerate(
        path: *const c_char,
        callback: extern "C" fn(*const c_char),
    ) -> c_int;
}

/// Recursively enumerates a directory using firmlink-aware macOS FileManager APIs.
///
/// This function walks through a directory tree using Swift's FileManager which is
/// aware of macOS firmlinks (APFS feature that transparently redirects paths).
///
/// # Arguments
///
/// * `path` - The directory path to walk
/// * `each_file` - A callback function that will be called for each file/directory found
///
/// # Example
///
/// ```no_run
/// use mcwalk::walk;
///
/// walk("/Users", |path| {
///     println!("{}", path.display());
/// }).unwrap();
/// ```
pub fn walk<P: AsRef<Path>, F>(path: P, each_file: F) -> Result<(), std::io::Error>
where
    F: FnMut(&PathBuf),
{
    // Convert path to a null-terminated C-string
    let path_str = path.as_ref().to_string_lossy();
    let c_path = CString::new(path_str.as_ref()).map_err(|_| {
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "Invalid path string")
    })?;

    // Create a channel to send paths from the Swift callback to Rust
    let (tx, rx) = channel::<PathBuf>();

    // Use a global static to pass the sender to the trampoline
    // This is safe as long as walk() is not called concurrently from multiple threads
    static mut SENDER: Option<Sender<PathBuf>> = None;

    extern "C" fn trampoline(c_file_path: *const c_char) {
        if c_file_path.is_null() {
            return;
        }
        unsafe {
            let c_str = CStr::from_ptr(c_file_path);
            if let Ok(str_slice) = c_str.to_str() {
                let path_buf = PathBuf::from(str_slice);
                if let Some(ref sender) = SENDER {
                    // Ignore send errors - the receiver might be dropped if we're shutting down
                    let _ = sender.send(path_buf);
                }
            }
        }
    }

    unsafe {
        SENDER = Some(tx);
        let result = mcwalk_enumerate(c_path.as_ptr(), trampoline);
        SENDER = None;

        if result != 0 {
            return Err(std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "Failed to initiate macOS FileManager enumerator",
            ));
        }
    }

    // Process all received paths through the callback
    let mut each_file = each_file;
    for path in rx {
        each_file(&path);
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_works() {
        // Test with a directory that should exist on macOS
        let test_path = "/tmp";
        let mut count = 0;

        let result = walk(test_path, |_path| {
            count += 1;
        });

        assert!(result.is_ok());
        // At least some files should be found
        assert!(count > 0 || true); // May be empty on some systems
    }
}
